set -euo pipefail
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gunzipSync,gzipSync} from 'node:zlib';import * as ch from 'cheerio';import {DatabaseSync} from 'node:sqlite';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {ThreeFlowState} from './src/newsFlow/threeFlowState.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {parsePublicPublicationFeed} from './src/web/newsDateContext.mjs';const root='/var/lib/news-flow/recovery-all-20261123',s=JSON.parse(fs.readFileSync(root+'/source-audit.json')),registry=await loadNewsRegistry(),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true});ThreeFlowState.prototype.loadOverlays.call({db,configureSites:()=>{}},registry);const network=new NewsNetworkPool({workers:1}),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,cache:()=>null,request:()=>null,reserve:()=>true,completeHttpResponse:()=>{}},network,pool,allowedDomains:registry.allowedDomains,siteCooldown:false});
try{for(const site of ['cadn.com.vn','vnbiznews.com']){const source=registry.sources.get(site),a=s.sites.find(p=>p.site===site).articles.find(p=>p.file),html=gunzipSync(fs.readFileSync(a.file)).toString(),$=ch.load(html),url=site==='cadn.com.vn'?'https://cadn.com.vn/tin-moi-nhat.rss':'https://vnbiznews.com/rss',p=await driver.get('recover-native-'+site,url,source.config,[],{reviewFailed:true,taskRole:'publication_feed'});if(p.html)fs.writeFileSync(root+'/'+site+'-native-feed.gz',gzipSync(p.html));const feed=parsePublicPublicationFeed(p.html||'',url);console.log(JSON.stringify({site,effectiveConfig:{timePolicy:source.config.publicationTimePolicy,timezone:source.config.timezone,provenance:source.config.timezoneProvenance},bodyChildren:$('article').first().children().map((i,e)=>({tag:e.tagName,id:$(e).attr('id'),class:$(e).attr('class'),chars:$(e).text().trim().length})).get(),articleText:$('.cadn-ct-post').text().trim().slice(0,500),feed:{status:p.statusCode,error:p.error,items:feed.items.slice(0,2),keys:Object.keys(feed),prefix:p.html?.slice(0,500)}}));}}finally{db.close();await network.close();}
NODE
